from typing import List, Dict, Any

def _handle_A(item: Dict[str, Any]) -> Dict[str, Any]:
    value = item["value"] * 2
    return {"id": item["id"], "value": value, "category": "high" if value > 100 else "low"}

def _handle_B(item: Dict[str, Any]) -> Dict[str, Any]:
    value = item["value"] + 50
    return {"id": item["id"], "value": value, "category": "adjusted"}

def _handle_C(item: Dict[str, Any]) -> Dict[str, Any]:
    if item["value"] < 0:
        return {"id": item["id"], "value": 0, "category": "clamped"}
    return {"id": item["id"], "value": item["value"], "category": "passthrough"}

_HANDLERS = {
    "A": _handle_A,
    "B": _handle_B,
    "C": _handle_C,
}

def _dispatch(item: Dict[str, Any]) -> Dict[str, Any]:
    handler = _HANDLERS.get(item.get("type"))
    if handler is None:
        raise ValueError(f"Unsupported type: {item.get('type')}")
    return handler(item)

def process_data(data: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    results = []
    for item in data:
        results.append(_dispatch(item))
    return results

