// TypeScript interfaces based on the inferred schema

export interface Preferences {
    theme: string;
    notifications: boolean;
    language: string;
}

export interface User {
    id: number;
    name: string;
    email: string;
    preferences: Preferences;
    tags: string[];
    lastLogin: string;
    metadata?: unknown; // Optional and nullable
}

/**
 * Validates a user object against the inferred schema.
 * Throws an error if any type or value constraint is violated.
 */
export function validateUser(user: unknown): void {
    if (typeof user !== 'object' || user === null) {
        throw new Error('User must be a non-null object');
    }

    const {
        id,
        name,
        email,
        preferences,
        tags,
        lastLogin,
        metadata
    } = user;

    // id: integer
    if (!Number.isInteger(id)) {
        throw new Error('id must be an integer');
    }

    // name: non-empty string
    if (typeof name !== 'string' || name.trim().length === 0) {
        throw new Error('name must be a non-empty string');
    }

    // email: string containing '@'
    if (typeof email !== 'string' || !email.includes('@')) {
        throw new Error('email must be a string containing "@"');
    }

    // preferences: object with required string/boolean fields
    if (typeof preferences !== 'object' || preferences === null) {
        throw new Error('preferences must be an object');
    }
    if (typeof preferences.theme !== 'string') {
        throw new Error('preferences.theme must be a string');
    }
    if (typeof preferences.notifications !== 'boolean') {
        throw new Error('preferences.notifications must be a boolean');
    }
    if (typeof preferences.language !== 'string') {
        throw new Error('preferences.language must be a string');
    }

    // tags: array of strings
    if (!Array.isArray(tags)) {
        throw new Error('tags must be an array');
    }
    for (const tag of tags) {
        if (typeof tag !== 'string') {
            throw new Error('All tags must be strings');
        }
    }

    // lastLogin: string (ISO date-time format assumed)
    if (typeof lastLogin !== 'string') {
        throw new Error('lastLogin must be a string');
    }

    // metadata: optional and nullable (any type)
    // No strict type check required, but if present, it must be an object or null
    if (metadata !== undefined && metadata !== null && typeof metadata !== 'object') {
        throw new Error('metadata must be an object, null, or undefined');
    }
}

// Example usage:
const validUser: User = {
    id: 12345,
    name: "Alice",
    email: "alice@example.com",
    preferences: {
        theme: "dark",
        notifications: true,
        language: "en"
    },
    tags: ["admin", "beta-tester"],
    lastLogin: "2024-01-15T10:30:00Z",
    metadata: null
};

validateUser(validUser); // Should pass without error
