"""CLI tool to analyze log files and count log levels."""

import argparse
import os
import sys
from collections import Counter


def count_log_levels(filepath):
    """Count occurrences of each log level in a log file."""
    counts = {"INFO": 0, "WARN": 0, "ERROR": 0, "DEBUG": 0}

    try:
        with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                # Match log level patterns at the start of the line
                for level in counts:
                    if line.startswith(f"{level} ") or line.startswith(f"{level}"):
                        counts[level] += 1
                        break
    except FileNotFoundError:
        print(f"Warning: File not found: {filepath}", file=sys.stderr)

    return counts


def main():
    parser = argparse.ArgumentParser(description="Analyze log files and count log levels.")
    parser.add_argument("directory", help="Directory containing .log files")
    parser.add_argument("--min-errors", type=int, default=None, help="Only show files with >=N errors")

    args = parser.parse_args()

    if not os.path.isdir(args.directory):
        print(f"Error: Directory not found: {args.directory}", file=sys.stderr)
        sys.exit(1)

    log_files = [f for f in os.listdir(args.directory) if f.endswith('.log')]

    if not log_files:
        print(f"No .log files found in {args.directory}")
        sys.exit(0)

    results = []
    for filename in sorted(log_files):
        filepath = os.path.join(args.directory, filename)
        counts = count_log_levels(filepath)
        results.append((filename, counts))

    # Print summary table
    print(f"{'File':<20} {'INFO':<8} {'WARN':<8} {'ERROR':<8} {'DEBUG':<8}")
    print("-" * 50)

    for filename, counts in results:
        if args.min_errors is not None and counts["ERROR"] < args.min_errors:
            continue

        print(f"{filename:<20} {counts['INFO']:<8} {counts['WARN']:<8} {counts['ERROR']:<8} {counts['DEBUG']:<8}")

    # If no files passed filter, show warning
    if args.min_errors is not None:
        files_with_errors = [r[0] for r in results if r[1]["ERROR"] >= args.min_errors]
        if not files_with_errors:
            print(f"Warning: No files have >= {args.min_errors} errors", file=sys.stderr)


if __name__ == "__main__":
    main()]]></param></function>
